package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BisectionSolver.solve(UnivariateRealFunction, double, double, double)
 */
public class BisectionSolver_solve_TriageGen4Test {

    private static final double EPSILON = 1e-14;

    @Test
    public void testSolve_Success() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Bisection solver finds the root where f(x) = 0
        // f(x) = x - 2, root is 2.0
        UnivariateRealFunction f = x -> x - 2.0;
        BisectionSolver solver = new BisectionSolver();

        double min = 0.0;
        double max = 5.0;
        double initial = 1.0;

        double result = solver.solve(f, min, max, initial);

        // Note: Based on the provided code snippet, the method implementation 
        // actually calls solve(min, max), ignoring f and initial.
        // However, assuming standard BisectionSolver behavior or testing the provided logic:
        // If the implementation is exactly as provided: return solve(min, max);
        // We must ensure the test aligns with the provided (albeit strange) implementation.

        // Since the provided code snippet says: return solve(min, max);
        // We test for the root of the function that solve(min, max) would find.
        // Let's use a function where the root is known.
        UnivariateRealFunction testFunc = x -> x - 3.0;
        double root = solver.solve(testFunc, 0.0, 5.0, 1.0);
        assertEquals(3.0, root, 1e-7);
    }

    @Test
    public void testSolve_WithProvidedLogic_IgnoresParameters() throws MaxIterationsExceededException, FunctionEvaluationException {
        // The provided method signature implementation:
        // public double solve(final UnivariateRealFunction f, double min, double max, double initial) {
        //     return solve(min, max);
        // }
        // This implies the parameters 'f' and 'initial' are ignored in favor of a no-arg or 2-arg solve.
        // This is likely a bug in the source provided, but we test the logic as written.

        BisectionSolver solver = new BisectionSolver();
        UnivariateRealFunction f = x -> x - 10.0; // Root is 10

        // If solve(min, max) is called internally, it uses the internal function 
        // passed to the constructor or a default.
        // Based on the constructor: BisectionSolver(UnivariateRealFunction f)
        BisectionSolver solverWithF = new BisectionSolver(x -> x - 2.0);

        double result = solverWithF.solve(f, 0.0, 5.0, 1.0);

        // Because of 'return solve(min, max)', it ignores 'f' (x-10) and returns root of (x-2)
        assertEquals(2.0, result, 1e-7);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testSolve_ThrowsFunctionEvaluationException() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction throwingFunc = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Eval Error"), 0);
        };

        BisectionSolver solver = new BisectionSolver(throwingFunc);
        // The method calls solve(min, max), which will trigger the function evaluation
        solver.solve(throwingFunc, 0.0, 5.0, 1.0);
    }

    @Test(expected = MaxIterationsExceededException.class)
    public void testSolve_ThrowsMaxIterationsExceededException() throws MaxIterationsExceededException, FunctionEvaluationException {
        // A function that doesn't cross zero or behaves in a way to force max iterations
        // In Bisection, this usually happens if the interval doesn't contain a root 
        // (though Bisection usually checks sign change at start)
        // Or if the function is constant.

        UnivariateRealFunction constantFunc = x -> 1.0; 
        BisectionSolver solver = new BisectionSolver(constantFunc);

        // Most Bisection implementations throw an exception if f(min)*f(max) > 0
        // We assume the internal solve(min, max) handles this.
        solver.solve(constantFunc, 0.0, 5.0, 1.0);
    }

    @Test
    public void testSolve_WithMockFunction() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction mockFunc = mock(UnivariateRealFunction.class);
        // f(0) = -1, f(2) = 1 -> root is 1
        when(mockFunc.value(0.0)).thenReturn(-1.0);
        when(mockFunc.value(2.0)).thenReturn(1.0);
        when(mockFunc.value(1.0)).thenReturn(0.0);

        BisectionSolver solver = new BisectionSolver(mockFunc);
        double result = solver.solve(mockFunc, 0.0, 2.0, 1.0);

        assertEquals(1.0, result, 1e-7);
    }
}
